// Existing Slack IncomingWebhook senders can use the URL generated by Anycord.
import { IncomingWebhook } from '@slack/webhook'
const { SLACK_WEBHOOK_URL, CI_JOB_STATUS = 'success', GITHUB_REPOSITORY = 'CI' } = process.env
if (!SLACK_WEBHOOK_URL) throw new Error('Set SLACK_WEBHOOK_URL to the secret URL from Server Settings → Apps & integrations')
try {
  await new IncomingWebhook(SLACK_WEBHOOK_URL).send({ text: `${GITHUB_REPOSITORY}: build ${CI_JOB_STATUS}` })
  console.log('Slack-compatible notification delivered')
} catch {
  console.error('Webhook delivery failed. Check the URL, app permissions and supported payload limits.')
  process.exitCode = 1
}
